gh api graphql \
  -F owner="ZimmermannAU" \
  -F name="zimmermann-pwa" \
  -F number="65" \
  -f query='
query($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      reviewThreads(first: 100) {
        totalCount
        nodes {
          isResolved
          isOutdated
          path
          line
          comments(first: 5) {
            nodes { author { login } body createdAt }
          }
        }
      }
    }
  }
}' > /private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/113175e9-2496-4539-9640-84df14f78583/scratchpad/pr65/review_threads.json
python3 -c "
import json
d = json.load(open('/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/113175e9-2496-4539-9640-84df14f78583/scratchpad/pr65/review_threads.json'))
nodes = d['data']['repository']['pullRequest']['reviewThreads']['nodes']
print('total threads:', d['data']['repository']['pullRequest']['reviewThreads']['totalCount'])
unresolved = [n for n in nodes if not n['isResolved']]
print('unresolved:', len(unresolved))
for n in unresolved:
    first = n['comments']['nodes'][0]
    print('---', n['path'], 'line', n['line'], '| outdated:', n['isOutdated'], '| author:', first['author']['login'], '| created:', first['createdAt'])
    print(first['body'][:400].replace(chr(10),' '))
    print()
"

content.text:
type NavItemProps = {
  className?: string;
  inverse?: boolean;
  menuItem?: string;
  state?: "Active" | "Default" | "Focus";
};

