import { NAV_LETTER_SPACING } from 'app/theme/components/navConstants';

// Extends the base Header theme (node_modules/.../theme/components/project/header.js).
// Parts not listed here inherit base styles unchanged.
export const Header = {
  parts: [
    'container',
    'content',
    'searchContainer',
    'bodyContainer',
    'logo',
    'icons',
    'agentIcon',
    'wishlistIcon',
    'accountIcon',
    'arrowDown',
    'signout',
    'signoutIcon',
    'signoutText',
    // Zimmermann additions:
    'topBar',
    'logoBar',
    'logoButton',
    'desktopActionButton',
    // navGroup → migrated to ZimmHeaderLeftBar.nav (leftBar/leftBar.css.ts)
    // iconGroup → migrated to ZimmHeaderRightBar.iconGroup (rightBar/rightBar.css.ts)
    // searchWrapper → migrated to ZimmHeaderRightBar.searchWrapper (rightBar/rightBar.css.ts)
  ],
  baseStyle: {
    container: {
      position: 'sticky',
      top: 0,
      zIndex: 'sticky',
      backgroundColor: 'var(--zimm-color-bg-07)',
      boxShadow: 'none',
      width: '100%',
      // No border — prototype header has no border/shadow
    },
    // No `content` part here, deliberately — same reasoning as the `logo` part note below:
    // base SFCC's `content` part sets paddingLeft/Right as a 4-element Chakra-spacing array
    // ([4,4,6,8]), and Chakra's multi-part recipe merge doesn't reliably let an override here
    // win at every breakpoint. Padding/maxWidth are set directly on the
    // <chakra.div __css={styles.content}> call site in header/index.tsx (HEADER_CONTENT_SX)
    // instead, bypassing the merge entirely. See that file for the actual values.
    bodyContainer: {
      // Un-do the base theme's flex: '1' so the nav takes natural width only,
      // letting topBar's space-between push Account/Saved/Bag to the right edge
      flex: 'none',
    },
    topBar: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      // py: 24px mobile (var(--alias/space/600)) | 48px tablet/desktop (var(--alias/space/1200))
      // Figma nodes 40000259:13476 (mobile), 40000259:13480 (tablet), 40000259:13481 (desktop)
      paddingTop: ['var(--zimm-scale-600)', null, 'var(--zimm-scale-1200)'],
      paddingBottom: ['var(--zimm-scale-600)', null, 'var(--zimm-scale-1200)'],
    },
    logoBar: {
      display: 'flex',
      alignItems: 'center',
      paddingTop: 0,
      // 48px (last step) has no named spacing.ts entry, only the numeric
      // --zimm-scale-1200 alias — same documented exception as zimmTokens.ts.
      paddingBottom: ['var(--zimm-scale-3xl)', 'var(--zimm-scale-3xl)', 'var(--zimm-scale-1200)'],
    },
    logoButton: {
      display: 'flex',
      alignItems: 'center',
      height: 'auto',
      minWidth: 'auto',
      padding: 0,
      _focus: { boxShadow: 'outline' },
      _focusVisible: { outline: 0 },
    },
    // No `logo` part here, deliberately. Base SFCC's own `logo` part
    // (theme/components/project/header.js) sets width/height as Chakra-spacing arrays
    // ([8,8,8,12]/[6,6,6,8]). Both an array override (positional gap at lg/xl/2xl) and a
    // fully-named object override ({base,sm,md,lg,xl,'2xl'}) were tried here and both still
    // lost to base's values at md/lg in the rendered CSS — Chakra's multi-part recipe merge
    // combines this part with the base theme's in a way that isn't a predictable per-key
    // override for this specific base-defined key. Rather than keep fighting that merge,
    // logo sizing is set directly on the <ZimmLogo sx={...}> call site in header/index.tsx
    // (HEADER_LOGO_SX), bypassing useMultiStyleConfig's part-merge entirely — a plain object
    // spread with no base theme involved at all. See that file for the actual values.
    desktopActionButton: {
      fontFamily: 'var(--zimm-font-family-heading)',
      fontSize: 'var(--zimm-font-size-3xs)',
      fontWeight: 'var(--zimm-font-weight-medium)',
      letterSpacing: NAV_LETTER_SPACING,
      color: 'var(--zimm-color-text-default)',
      height: 'auto',
      minWidth: 'auto',
      padding: 0,
      paddingBottom: 'var(--zimm-scale-3xs)',
      position: 'relative',
      // Slide-in underline on hover — matches prototype's ::after scaleX animation
      _after: {
        content: '""',
        position: 'absolute',
        bottom: 0,
        left: 0,
        width: '100%',
        height: 'var(--zimm-border-width-default)',
        background: 'currentColor',
        transform: 'scaleX(0)',
        transformOrigin: 'right center',
        // 0.25s matches no motion token (fast 200ms / default 300ms) — left as-is
        // pending the UI designer's confirmation, same treatment as zimmButton.css.ts's
        // own untokenised 0.15s.
        transition: 'transform 0.25s ease',
      },
      _hover: {
        _after: {
          transform: 'scaleX(1)',
          transformOrigin: 'left center',
        },
      },
    },
  },
};

