const dialog = document.querySelector('[aria-label="Clothing menu"], [role="dialog"]');
if (!dialog) {
  JSON.stringify({found: false});
} else {
  const cs = getComputedStyle(dialog);
  const rect = dialog.getBoundingClientRect();
  // walk up a couple levels for the animated wrapper
  const parent = dialog.parentElement;
  const parentCs = parent ? getComputedStyle(parent) : null;
  JSON.stringify({
    found: true,
    tag: dialog.tagName,
    rect: {width: Math.round(rect.width), height: Math.round(rect.height), top: Math.round(rect.top)},
    display: cs.display,
    opacity: cs.opacity,
    visibility: cs.visibility,
    gridTemplateRows: cs.gridTemplateRows,
    parentGridTemplateRows: parentCs ? parentCs.gridTemplateRows : null,
    parentOpacity: parentCs ? parentCs.opacity : null,
  }, null, 2);
}

