  opacity: cs ? cs.opacity : null,
  visibility: cs ? cs.visibility : null,
});

const dialog = document.querySelector('[aria-label="Clothing menu"]');
JSON.stringify({
  innerHTMLLength: dialog ? dialog.innerHTML.length : null,
  linkCount: dialog ? dialog.querySelectorAll('a').length : null,
  textContent: dialog ? dialog.textContent.trim().slice(0, 200) : null,
  childElementCount: dialog ? dialog.childElementCount : null,
  outerHTMLSnippet: dialog ? dialog.outerHTML.slice(0, 500) : null,
});

const dialog = document.querySelector('[aria-label="Clothing menu"]');
const link = dialog.querySelector('a');
const linkCs = getComputedStyle(link);
const dialogCs = getComputedStyle(dialog);
const rect = link.getBoundingClientRect();
// check what's actually painted at that screen point
const topEl = document.elementFromPoint(rect.left + 5, rect.top + 5);
JSON.stringify({
  linkText: link.textContent,
  linkColor: linkCs.color,
  linkFontSize: linkCs.fontSize,
  linkOpacity: linkCs.opacity,
  linkRect: {x: Math.round(rect.left), y: Math.round(rect.top), w: Math.round(rect.width), h: Math.round(rect.height)},
  dialogBg: dialogCs.backgroundColor,
  dialogZIndex: dialogCs.zIndex,
  dialogPosition: dialogCs.position,
  elementActuallyAtThatPoint: topEl ? {tag: topEl.tagName, cls: topEl.className, isTheLink: topEl === link} : null,
});

const link = document.querySelector('[aria-label="Clothing menu"] a');
let el = link;
const chain = [];
while (el && el !== document.documentElement) {
  const cs = getComputedStyle(el);
