  const cs = getComputedStyle(d);
  return {name, height: Math.round(d.getBoundingClientRect().height), opacity: cs.opacity, visibility: cs.visibility};
});
const underlinedTrigger = [...document.querySelectorAll('nav#list-menu button, nav#list-menu a')].find(el => {
  const cs = getComputedStyle(el, '::after');
  return cs.transform && cs.transform !== 'none' && cs.transform !== 'matrix(0, 0, 0, 0, 0, 0)';
});
JSON.stringify({ dialogs, underlinedTriggerText: underlinedTrigger?.textContent }, null, 1);

