import React, { Fragment, useEffect, useLayoutEffect, useRef, useState } from 'react';
import { ListMenuContent } from '@salesforce/retail-react-app/app/components/list-menu/list-menu-content';
import {
  Box,
  Popover,
  PopoverContent,
  PopoverBody,
  useTheme,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { ListMenuTrigger } from './list-menu-trigger';
import { useUiCopy } from 'app/hooks/useUiCopy';
import type { MegaMenuMotionPhase } from 'app/hooks/useMegaMenuMotion';
import type { HeaderNavItemEntry } from 'app/types/contentful';
import type { HeaderNavTriggerElement } from 'app/hooks/useHeaderNavKeyboard';

// Any real, visible focusable content a mega-menu panel can contain (leaf links; a bare
// <button> never occurs there today, included for robustness) — see focusFirstPanelLink below.
const PANEL_FOCUSABLE_SELECTOR = 'a[href], button:not([disabled])';

// Height reveal targets 'expanding'/'collapsing' only — a switch between items must never move
// the height, so its 'contentIn' target snaps to 1fr with no transition instead of re-running
// the reveal. See useMegaMenuMotion.ts for the full phase state machine.
const isPanelExpanded = (phase: MegaMenuMotionPhase) => phase !== 'closed' && phase !== 'collapsing';
const isPanelHeightAnimating = (phase: MegaMenuMotionPhase) => phase === 'expanding' || phase === 'collapsing';
const isContentVisible = (phase: MegaMenuMotionPhase) => phase === 'contentIn' || phase === 'open';

/**
 * Enabling a CSS `transition` and changing the property it targets in the same React commit
 * gives the browser no prior painted frame to interpolate from — it snaps straight to the
 * target with zero animation and no `transitionend`, which stalls useMegaMenuMotion's phase
 * machine forever waiting on a completion event that never comes (confirmed empirically:
 * grid-template-rows reached its final value within 50ms with no interpolation).
 *
 * Fix: defer the value change by two `requestAnimationFrame`s whenever it should animate (one
 * rAF isn't reliably enough to cross a real paint boundary), so the transition is already
 * active on a genuine prior frame before the target changes. Applies instantly otherwise.
 */
const useTransitionSafeValue = <TValue,>(target: TValue, shouldAnimate: boolean, initial: TValue): TValue => {
  const [value, setValue] = useState(initial);

  useLayoutEffect(() => {
    if (!shouldAnimate) {
      setValue(target);
      return undefined;
    }
    let secondFrame = 0;
    const firstFrame = requestAnimationFrame(() => {
      secondFrame = requestAnimationFrame(() => setValue(target));
    });
    return () => {
      cancelAnimationFrame(firstFrame);
      if (secondFrame) cancelAnimationFrame(secondFrame);
    };
  }, [target, shouldAnimate]);

  return value;
};

type ListMenuPopoverProps = {
  contentComponent?: React.ElementType;
  item?: HeaderNavItemEntry;
  name?: string;
  itemsKey?: string;
  maxColumns?: number;
  /**
   * Controlled by ListMenuView (a single source of truth shared across every sibling
   * ListMenuPopover) rather than each instance owning its own useDisclosure() — necessary for
   * mutual exclusion, since this override's `closeOnBlur={false}` means nothing else closes an
   * already-open item.
   *
   * True for *both* the outgoing item and the incoming one during a switch, not just the
   * active one — see `isActiveItem` below for why.
   */
  isOpen: boolean;
  onOpen: () => void;
  onClose: () => void;
  /**
   * Whether THIS item is the one useMegaMenuMotion considers *active* (not merely pending) —
   * distinct from `isOpen` above. During a switch, the pending (incoming) item is `isOpen` but
   * not yet `isActiveItem`: its Popover mounts/positions early, while the outgoing item's
   * content still covers the page, so there's no positioning left to do once it actually takes
   * over — without this, a real flash-of-page-content gap appeared between the outgoing
   * Popover closing and the incoming one finishing its own first-open positioning. The pending
   * item's own CSS phase stays 'closed' throughout — only its Popover mount state moves early.
   */
  isActiveItem?: boolean;
  /**
   * Whether THIS item's L1 trigger should show as active/underlined — the most recently
   * *hovered* item, which changes instantly. Distinct from `isOpen`/`isActiveItem` above (which
   * stay true for the outgoing item throughout a switch's fade-out) so both triggers' underlines
   * animate concurrently instead of the outgoing one waiting for the switch to finish.
   */
  isTriggerActive?: boolean;
  /** The shared mega-menu motion phase — only meaningful for the instance where `isActiveItem`
   *  is true (see `phase` below). */
  motionPhase?: MegaMenuMotionPhase;
  onExpandComplete?: () => void;
  onContentInComplete?: () => void;
  onContentOutComplete?: () => void;
  onCollapseComplete?: () => void;
  /** Merged onto the trigger's real DOM node — see useHeaderNavKeyboard.ts. */
  triggerRef?: React.Ref<HeaderNavTriggerElement>;
  /** Left/Right/Home/End roving focus across L1 triggers — see useHeaderNavKeyboard.ts. */
  onTriggerKeyDown?: (event: React.KeyboardEvent) => void;
};

// Override of base list-menu-popover.jsx: content is always rendered (Chakra's Popover hides
// closed content on its own — an a11y improvement over gating with `{isOpen && ...}`).
// closeOnBlur={false} + no onMouseLeave: the menu only closes via the Close control, a leaf
// link, or Escape. Imports our own list-menu-trigger.tsx override instead of base.
const ListMenuPopover = ({
  contentComponent,
  item,
  name,
  itemsKey,
  maxColumns,
  isOpen,
  onOpen,
  onClose,
  isActiveItem,
  isTriggerActive,
  motionPhase,
  onExpandComplete,
  onContentInComplete,
  onContentOutComplete,
  onCollapseComplete,
  triggerRef,
  onTriggerKeyDown,
}: ListMenuPopoverProps) => {
  const initialFocusRef = useRef<HTMLElement>(null);
  const ContentComponent = contentComponent || ListMenuContent;
  const theme = useTheme() as { components: Record<string, { baseStyle: Record<string, Record<string, unknown>> }> };
  const { baseStyle } = theme.components.ListMenu;
  const { t } = useUiCopy();

  // A pending (isOpen yet not-yet-active) instance must stay at the 'closed' resting state —
  // every completion callback below is guarded by an exact phase match, so a spurious
  // transitionend on a non-active instance can never fire one of them.
  const phase: MegaMenuMotionPhase = isActiveItem ? motionPhase ?? 'closed' : 'closed';
  const gridTemplateRowsTarget = isPanelExpanded(phase) ? '1fr' : '0fr';
  const gridTemplateRows = useTransitionSafeValue(gridTemplateRowsTarget, isPanelHeightAnimating(phase), '0fr');

  // Per the W3C WAI-ARIA APG's Disclosure Navigation Menu pattern (the canonical reference for
  // this exact "top-level link that also opens a dropdown" shape — confirmed against
  // https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/examples/disclosure-navigation/'s own
  // keyboard-support table): opening the menu leaves focus on the trigger — it does NOT jump
  // into the panel — and Down Arrow (list-menu-trigger.tsx's onEnterPanel) is the documented
  // fast-path a keyboard user takes from there into the panel's first link. Tab still flows
  // through the open panel's own links afterwards, same as any other revealed content in normal
  // document order — nothing here needs to intercept Tab. `autoFocus={false}` below exists only
  // to stop Chakra's own default (which would otherwise move focus into the panel the instant
  // isOpen flips true, for every open method including a mouse hover) from fighting this.
  const focusFirstPanelLink = () => {
    initialFocusRef.current?.querySelector<HTMLElement>(PANEL_FOCUSABLE_SELECTOR)?.focus();
  };

  // Down Arrow can be pressed the instant the panel opens, before its reveal/fade animation has
  // actually finished (confirmed live against a real browser: fast keyboard input landed focus
  // on a link that was still 0-height/opacity-0 — the same WCAG 2.4.7 bug the old auto-focus-on-
  // open behaviour had, just reachable through this new path instead). If the panel is already
  // fully open, focus moves immediately; otherwise the request is remembered and fulfilled once
  // phase actually reaches 'open', not merely 'contentIn' (opacity is still ramping up then —
  // see isContentVisible's own comment; only 'open' means the transition has genuinely settled).
  const pendingEnterPanelRef = useRef(false);
  const onEnterPanel = () => {
    if (phase === 'open') {
      focusFirstPanelLink();
    } else {
      pendingEnterPanelRef.current = true;
    }
  };
  useEffect(() => {
    // A Down Arrow press can be followed by the menu closing (or switching to a different item)
    // before the panel ever reaches 'open' — without this, the stale request would fire later
    // when this item re-opens via a plain pointer hover, moving focus with no new keyboard input.
    // isOpen must be a dependency, not just phase: a pending (isOpen yet not-yet-active) instance
    // has phase permanently stuck at 'closed' (see the `phase` derivation above), so isOpen
    // flipping false on its own would never otherwise re-run this effect to clear the ref.
    if (!isOpen || phase === 'closed') {
      pendingEnterPanelRef.current = false;
      return;
    }
    if (phase === 'open' && pendingEnterPanelRef.current) {
      pendingEnterPanelRef.current = false;
      focusFirstPanelLink();
    }
  }, [isOpen, phase]);

  return (
    <Box>
      <Popover
        placement="bottom-start"
        initialFocusRef={initialFocusRef}
        // Chakra Popover's own focus-management toggle, not the native HTML autofocus attribute
        // jsx-a11y/no-autofocus exists to catch — disabled deliberately: Chakra's autoFocus
        // would move focus into the panel the instant isOpen flips true, for every open method
        // including a mouse hover, which the Disclosure Navigation pattern comment above this
        // component explicitly does not want. Focus stays on the trigger; see that comment.
        // eslint-disable-next-line jsx-a11y/no-autofocus
        autoFocus={false}
        onOpen={onOpen}
        onClose={onClose}
        isOpen={isOpen}
        variant="fullWidth"
        closeOnBlur={false}
      >
        <Fragment>
          <ListMenuTrigger
            item={item}
            name={name}
            isActive={isTriggerActive}
            onOpen={onOpen}
            onClose={onClose}
            // Only wired while actually open — ArrowDown on the trigger is a no-op while closed
            // (Space/Enter/click remain the only way to open it). Gating here, not just inside
            // onEnterPanel itself, matters: without it, an ArrowDown press on a closed trigger
            // could arm the pending-focus flag above and then fire later if the menu happens to
            // open via some other means (e.g. a hover) — this way it's a true no-op instead.
            onEnterPanel={isOpen ? onEnterPanel : undefined}
            triggerRef={triggerRef}
            onTriggerKeyDown={onTriggerKeyDown}
          />
          {/* Focus-return-on-close (Chakra's own useFocusOnHide, trigger="click" default) needs
              this same ref — Popover clones it onto ListMenuTrigger's element internally via
              PopoverTrigger, so no separate wiring is needed here for that half. */}
          <PopoverContent
            data-testid="popover-menu"
            aria-label={t('list_menu.popover.assistive_msg.dialog_name', '{name} menu', { name: name ?? '' })}
            {...baseStyle.popoverContent}
          >
            <PopoverBody {...baseStyle.popoverBody}>
              {/* grid-template-rows 0fr<->1fr — animates to/from an unknown height with no JS
                  measurement, works for both desktop's fixed and tablet's fluid promo image. */}
              <Box
                data-testid="panel-reveal"
                {...baseStyle.panelRevealWrapper}
                sx={{
                  gridTemplateRows,
                  transition: isPanelHeightAnimating(phase)
                    ? 'grid-template-rows var(--zimm-motion-duration-default) ease-in'
                    : 'none',
                }}
                onTransitionEnd={(e: React.TransitionEvent<HTMLDivElement>) => {
                  if (e.target !== e.currentTarget) return;
                  if (phase === 'expanding') onExpandComplete?.();
                  if (phase === 'collapsing') onCollapseComplete?.();
                }}
              >
                <Box {...baseStyle.panelRevealInner}>
                  <Box
                    data-testid="panel-content-fade"
                    sx={{
                      opacity: isContentVisible(phase) ? 1 : 0,
                      transition: 'opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-fades)',
                    }}
                    onTransitionEnd={(e: React.TransitionEvent<HTMLDivElement>) => {
                      if (e.target !== e.currentTarget) return;
                      if (phase === 'contentIn') onContentInComplete?.();
                      if (phase === 'contentOut') onContentOutComplete?.();
                    }}
                  >
                    <ContentComponent
                      item={item}
                      itemsKey={itemsKey}
                      initialFocusRef={initialFocusRef}
                      onClose={onClose}
                      maxColumns={maxColumns}
                      isOpen={isOpen}
                      isFullyOpen={phase === 'open'}
                    />
                  </Box>
                </Box>
              </Box>
            </PopoverBody>
          </PopoverContent>
        </Fragment>
      </Popover>
    </Box>
  );
};

export { ListMenuPopover };

