import type { ImageEntry } from 'app/types/contentful';

export type ResolvedImage = {
  src: string;
  alt: string;
};

/**
 * Resolves a Contentful `image` entry (the reusable asset + accessible-metadata primitive —
 * see ImageEntry's own doc comment) down to the `{src, alt}` shape every `<Image>` render site
 * actually needs. Shared by megaMenuContent/toMegaMenuItem.ts (desktop/tablet) and
 * drawer-menu/index.tsx (mobile L2) — both resolve the same field shape.
 *
 * `decorative` short-circuits to an empty alt (screen readers skip it) regardless of whether
 * `altText` also happens to be set — an editor marking an image decorative is asserting no
 * fallback is warranted, not just skipping the field. Absent decorative/altText, falls back to
 * the underlying asset's own description/title, matching this field's pre-migration behaviour
 * when it linked a raw Asset directly.
 *
 * @param image the `promoImage`-shaped field value, or undefined if unset
 * @returns the resolved `{src, alt}`, or undefined if no image/asset is actually linked
 */
export const resolveImageEntry = (image: ImageEntry | undefined): ResolvedImage | undefined => {
  const asset = image?.fields.asset;
  if (!asset) return undefined;

  const alt = image.fields.decorative ? '' : image.fields.altText ?? asset.fields.description ?? asset.fields.title;

  return { src: asset.fields.file.url, alt };
};

content.text:
Good hypothesis to check, but it doesn't hold up — and the code makes it easy to see why.

`resolveImageEntry.ts` (the function that produces the URL both `megaMenuContent` and `drawer-menu` actually use) does exactly one thing:

```ts
export const resolveImageEntry = (image) => {
  const asset = image?.fields.asset;
  if (!asset) return undefined;        // ← only "no image linked at all" bails out
  ...
  return { src: asset.fields.file.url, alt };   // ← always the raw URL, no exceptions
};
```

There's no branch in there for "is this a placeholder" or "does this asset have processed variants yet" — there's exactly one path, and it always returns the raw file URL. It doesn't check anything about the asset's *readiness*, only whether one is linked *at all*. Whether the image sitting in Contentful right now is a final production photo or a temporary placeholder makes zero difference here — either way, this function hands back the same unprocessed URL.

The optimization pipeline (`buildContentfulResponsiveImage`) works purely on URL parameters against Contentful's CDN — it doesn't care whether the underlying asset is "final" either. So even a placeholder image would get the size/format benefit if the code called it.

That's what makes this a code gap rather than a content gap: the two things are actually independent. Whoever finishes populating the real promo images later would hit the exact same unoptimized behavior, because nothing in the code path changes based on what's uploaded — only whether the pipeline gets called at all, which right now is nowhere.

